using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Threading.Tasks;using System.Windows.Forms;
partial class Usagi {
    sealed class RapSession {internal Usagi Owner;internal RapTrack Track;internal readonly Stopwatch Clock=new Stopwatch();internal readonly List<Usagi> Pets=new List<Usagi>();internal bool AudioStarted,Stopped;internal Func<double> TimeSource=null;internal double Time {get{if(TimeSource!=null)return TimeSource();double? position=AudioStarted?Owner.sounds.RapPosition:null;return position.HasValue?position.Value:Clock.Elapsed.TotalSeconds;}}}
    static RapSession activeRap;static volatile RapTrack selectedRap;static volatile bool rapImporting;static volatile bool rapNeedsSelection;
    static string RapPath {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"UsagiPet","rap.wav");}}
    static string DefaultRapPath {get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"sounds","rap.wav");}}
    RapSession rapSession;int rapPlace,rapPhrase=-1;bool rapInPlace;ToolStripItem rapMenu,rapChangeMenu;
    bool PerformingRap {get{return rapSession!=null&&!rapSession.Stopped;}}
    void AddRapMenu(){rapMenu=new BubbleMenuItem("우사기 랩");rapMenu.Click+=(s,e)=>{if(activeRap!=null){StopRap(activeRap);return;}if(rapImporting)return;if(rapNeedsSelection){ChooseRapFile(true);return;}if(selectedRap!=null){BeginRap(selectedRap);return;}if(File.Exists(RapPath))LoadRapFile(RapPath,true,false);else if(File.Exists(DefaultRapPath))LoadRapFile(DefaultRapPath,true,false);else ChooseRapFile(true);};menu.Items.Add(rapMenu);rapChangeMenu=new BubbleMenuItem("랩 음원 바꾸기…");rapChangeMenu.Click+=(s,e)=>ChooseRapFile(false);RefreshRapMenu();}
    void RefreshRapMenu(){if(rapMenu==null)return;rapMenu.Text=rapImporting?"랩 음원 준비 중…":activeRap!=null?"랩 그만하기":"우사기 랩";rapMenu.Enabled=!rapImporting;if((selectedRap!=null||File.Exists(RapPath)||File.Exists(DefaultRapPath))&&!settingsReady&&!menu.Items.Contains(rapChangeMenu)){rapChangeMenu.Size=new Size(220,33);menu.Items.Insert(menu.Items.IndexOf(rapMenu)+1,rapChangeMenu);}rapChangeMenu.Enabled=!rapImporting;}
    void ChooseRapFile(bool start){if(rapImporting)return;using(var dialog=new OpenFileDialog{Title="랩 음원 선택 · WAV, 최대 90초",Filter="WAV 음원 (*.wav)|*.wav",CheckFileExists=true,Multiselect=false})if(dialog.ShowDialog()==DialogResult.OK){if(activeRap!=null)StopRap(activeRap);LoadRapFile(dialog.FileName,start,true);}}
    void LoadRapFile(string path,bool start,bool copy){rapImporting=true;RefreshRapMenu();Task.Factory.StartNew(()=>{try{var track=RapTrack.Load(path);if(copy)track.Save(RapPath);selectedRap=track;rapImporting=false;rapNeedsSelection=false;UpdatePost(()=>{RefreshRapMenu();if(start)BeginRap(track);});}catch(Exception error){rapImporting=false;rapNeedsSelection=selectedRap==null;UpdatePost(()=>{rapMenu.Text="랩 음원 다시 선택";rapMenu.Enabled=true;rapMenu.ToolTipText=error.Message;MessageBox.Show(this,error.Message,"랩 음원",MessageBoxButtons.OK,MessageBoxIcon.Information);});}});}
    void BeginRap(RapTrack track){if(activeRap!=null)StopRap(activeRap);LeaveFoodRace();CancelSocial();scatterActive=false;paused=false;pendingClicks=0;hopHeight=0;idleTime=0;speed=0;Change(Mood.Look);
        var session=new RapSession{Owner=this,Track=track};activeRap=session;session.Pets.Add(this);rapSession=session;rapPlace=0;rapInPlace=true;rapPhrase=-1;
        foreach(var peer in livePets)if(SameFloor(peer)&&!peer.SocialBusy&&peer.mood!=Mood.Sleep&&peer.mood!=Mood.Drowsy&&Math.Abs(peer.x-x)<520){peer.CancelSocial();peer.sounds.StopAll();peer.rapSession=session;peer.rapPlace=session.Pets.Count;peer.rapInPlace=false;peer.speechTime=0;session.Pets.Add(peer);}
        session.AudioStarted=sounds.PlayRap(track.Samples);session.Clock.Start();RefreshRapMenu();
    }
    static void StopRap(RapSession session){if(session==null||session.Stopped)return;session.Stopped=true;session.Clock.Stop();if(activeRap==session)activeRap=null;if(!session.Owner.IsDisposed)session.Owner.sounds.StopRap();foreach(var pet in session.Pets.ToArray())if(!pet.IsDisposed&&pet.rapSession==session){pet.rapSession=null;pet.rapInPlace=false;pet.speed=0;pet.moving=false;pet.hopHeight=0;pet.speechTime=0;pet.Change(Mood.Look);pet.socialBreak=2;pet.decisionTime=1+pet.rng.NextDouble()*2;pet.RefreshRapMenu();}if(activeRap==session)activeRap=null;}
    void LeaveRap(){var session=rapSession;if(session==null)return;if(session.Owner==this){StopRap(session);return;}session.Pets.Remove(this);rapSession=null;rapInPlace=false;hopHeight=0;}
    void TickRap(){var session=rapSession;if(session==null)return;if(session.Stopped||session.Owner.IsDisposed||session.Time>=session.Track.Duration||(session.AudioStarted&&!session.Owner.sounds.RapPlaying)){StopRap(session);return;}if(pointerDown||dragging||paused||foodActive){LeaveRap();}}
    bool UpdateRap(double dt){var session=rapSession;if(session==null||session.Stopped)return false;idleTime=0;settling=null;autoHopIn=Math.Max(2,autoHopIn);tripCooldown=Math.Max(2,tripCooldown);
        if(session.Owner!=this){double gap=35*(scale+session.Owner.scale)+12;int side=rapPlace%2==1?-1:1;double target=session.Owner.x+session.Owner.Width/2+side*((rapPlace+1)/2)*gap;rapInPlace=SocialMove(dt,target,105,7);}
        if(rapInPlace){moving=false;speed=0;if(mood!=Mood.Look)Change(Mood.Look);if(session.Owner==this){int phrase=(int)(session.Time/.72);if(phrase!=rapPhrase){rapPhrase=phrase;words=new[]{"야하!","우라!","푸루야!","우라라!"}[phrase%4];speechTime=.9;nextSpeechTime=7+rng.NextDouble()*3;}}}return true;
    }
    float RapPulse(){if(!PerformingRap)return 0;double time=rapSession.Time;return (float)(Math.Pow(Math.Max(0,Math.Sin(time*rapSession.Track.Bpm/60*Math.PI*2)),2)*.35+rapSession.Track.Level(time)*.65);}
    void DrawRapMicrophone(Graphics g,float width){if(!PerformingRap||rapSession.Owner!=this)return;float px=width/2+5*scale;using(var dark=new Pen(Color.FromArgb(93,66,46),2*scale)){dark.StartCap=dark.EndCap=LineCap.Round;g.DrawLine(dark,px,-36*scale,px,-2*scale);g.DrawLine(dark,px-8*scale,-2*scale,px+8*scale,-2*scale);}using(var head=new SolidBrush(Color.FromArgb(72,78,83)))g.FillEllipse(head,px-5*scale,-48*scale,10*scale,15*scale);using(var shine=new Pen(Color.FromArgb(185,194,194),1*scale))g.DrawArc(shine,px-3*scale,-46*scale,6*scale,10*scale,180,120);}
}
